button.clickEventHandler:
ESS.network.sendRequest(`/api/functions/CheckAssignmentInProcess?assignmentId=${data.id}`)
  .then(function (isAssignmentInProcess) {
    if (isAssignmentInProcess) {
      var isAssignmentBlocked = ESS.network.sendRequest(`/api/functions/IsAssignmentCardBlocked?assignmentId=${data.id}`);
      isAssignmentBlocked
        .then(message => {
          if (!message) {
            var url = `/api/functions/GetShiftVacationError?assignmentId=${data.id}`;
            ESS.network.sendRequest(url)
              .then(function (error) {
                if (error.length == 0) {
                  const actionParameters = {
                    id: 'ShiftVacation',
                    parameters: [
                      {
                        name: "Initiator",
                        type: "FacilityParameterQuery",
                        defaultValue: data.performer,
                        isRequired: true,
                        isCollection: false,
                        properties: {
                          dataSourceValueField: "id",
                          dataSourceCaptionField: "name"
                        }
                      }
                    ]
                  };
                  const attachmentGroup = 'VacationNoticeAttachmentGroup';
                  var documents = [];
                  var documentGroups = data.attachments.filter(function (x) {
                    return x.group === attachmentGroup;
                  });
                  documentGroups.forEach(function (a) {
                    return documents.push({ id: a.id, title: a.title });
                  });
                  ESS.actions.facilityActions.runFacility(actionParameters, { parameters: { AssignmentId: data.id, InitiatorId: data.performer, ApprovalDocuments: documents } }, sender);
                }
                else {
                  ESS.toasts.showErrorToastWithLog(error, ESS.L('@HRPROVACATIONS.ERROR_ASSIGNMENT_COMPLETION_FAILURE'));
                }
              })
          } else {
            ESS.toasts.showToast(message, 'danger', false);
          }
        }).catch(function (err) {
          ESS.toasts.showErrorToastWithLog(err);
        });
    } else {
      ESS.toasts.showToast(ESS.L('@HRPROSTATEMENTS.ASSIGNMENT_IS_ALREADY_COMPLETED'), 'danger', false);
    }
  }).catch(function (err) {
    ESS.toasts.showErrorToastWithLog(err);
  });

        var url = `/api/functions/GetShiftVacationError?assignmentId=${data.id}`;
        ESS.network.sendRequest(url)
        .then(function (error) 
        {
          if (error.length != 0)
          {
            ESS.toasts.showErrorToastWithLog(error, ESS.L('@HRPROVACATIONS.ERROR_ASSIGNMENT_COMPLETION_FAILURE'));
            ESS.closeElement(sender);         
          }        
          else
          {        
            var attachmentGroup = 'VacationNoticeAttachmentGroup';
            var serviceUrl = `/api/functions/GetEmployeeCertificates`;
            ESS.network.sendRequest(serviceUrl)
            .then(function (certs) {
              var callback = function callback() {
                ESS.network.sendRequest(`/api/functions/CheckAssignmentInProcess?assignmentId=${data.id}`)
                  .then(function (isAssignmentInProcess) {
                    if (isAssignmentInProcess) {
                      var isAssignmentBlocked = ESS.network.sendRequest(`/api/functions/IsAssignmentCardBlocked?assignmentId=${data.id}`);
                      isAssignmentBlocked
                        .then(message => {
                          if (!message) {
                            ESS.actions.workProcessActions.changeWorkItemState(data, 'Complete', 'Complete').then(function () {
                              ESS.closeElement(sender);
                              ESS.toasts.showToast(ESS.L('@HRPROVACATIONS.OBJECTCARD_VACATIONCONFIRMATIONASSIGNMENTOBJECTCARD_FACILITY_SUCCESSMESSAGE'), 'success', true);
                              ESS.widgets.updateWidgets();
                            }).catch(function (error) {
                              ESS.toasts.showErrorToastWithLog(ESS.L('@HRPROSTATEMENTS.ERR_ASSIGNMENT_COMPLETION_FAILURE'), error.message);
                          });
                          } else {
                            ESS.toasts.showToast(message, 'danger', false);
                          }
                        }).catch(function (err) {
                          ESS.toasts.showErrorToastWithLog(err);
                        });
                    } else {
                      ESS.toasts.showToast(ESS.L('@HRPROSTATEMENTS.ASSIGNMENT_IS_ALREADY_COMPLETED'), 'danger', false);
                    }
                  }).catch(function (err) {
                    ESS.toasts.showErrorToastWithLog(err);
                  });   
              };
              
              var documents = [];
              var documentGroups = data.attachments.filter(function (x) {
                return x.group === attachmentGroup;
              });
              documentGroups.forEach(function (a) {
                return documents.push({ id: a.id, title: a.title });
              });
              
              ESS.network.sendRequest(`/api/functions/CheckAssignmentInProcess?assignmentId=${data.id}`)
              .then(function(isAssignmentInProcess) {
                if (isAssignmentInProcess) {
                  var isAssignmentBlocked = ESS.network.sendRequest(`/api/functions/IsAssignmentCardBlocked?assignmentId=${data.id}`);
                  isAssignmentBlocked
                    .then(message => {
                    if (!message) { 
                      ESS.signing.sign({
                        certificates: certs,
                        documents,
                        documentGroup: 'IElectronicDocuments',
                        systemName: data.system,
                        signatureType: 'Approval',
                        packageTitle: data.title,
                        signedBy: data.performer,
                        callback,
                      });
                    } else {
					            ESS.toasts.showToast(message, 'danger', false);
					          }}).catch(function (err) {
                      ESS.toasts.showErrorToastWithLog(err);
                    });
                } else { 
                  ESS.toasts.showToast(ESS.L('@HRPROSTATEMENTS.ASSIGNMENT_IS_ALREADY_COMPLETED'), 'danger', false);
                }}).catch(function (err) {
                  ESS.toasts.showErrorToastWithLog(err);
                });
            })
            .catch(function (err) {
              ESS.toasts.showErrorToastWithLog(err);
            });
          }
        })

objectCard.openedEventHandler:
      ESS.network.sendRequest(`/api/functions/GetSubstituteFromAssignment?assignmentId=${data.id}`)
      .then(function (substituteInfo) {
        const substituteId = substituteInfo.SubstituteId;
        ESS.network.sendRequest(`/api/functions/GetSubstitutePositionAndJobTitle?employeeId=${substituteId}`)
        .then(function (substitutePosition) {
          ESS.network.sendRequest(`/api/functions/GetNotifiableFromAssignment?assignmentId=${data.id}`)
          .then(function (notifiables) {
            data.notifiableList = notifiables.NotifiableNames;
            data.notifiableIds = notifiables.NotifiableIds;
            data.substituteId = substituteId;
            data.substitute = substituteInfo.SubstituteName;

            ESS.network.sendRequest(`/api/functions/GetVacAppAInstruction?assignmentId=${data.id}`)
            .then(function (gluedInstruction) 
            {
              configuration.content = ESS.L('@HRPROVACATIONS.COMMON_INSTRUCTION') + '<br/><br/>' + gluedInstruction;
              resolve({configuration: configuration, data: data});
            });
          });
        });
      })
      .catch(function (error) {
        ESS.toasts.showToast(error.message, 'danger', false);
        reject();
		});
